// Chapter-local finite executions. No bounded execution certifies an impossibility theorem.
export const SRC={flp:'https://groups.csail.mit.edu/tds/papers/Lynch/jacm85.pdf',herlihy:'https://cs.brown.edu/people/mph/Herlihy91/p124-herlihy.pdf',dls:'https://groups.csail.mit.edu/tds/papers/Lynch/jacm88.pdf',kset:'https://courses.csail.mit.edu/6.852/08/papers/SaksZaharoglu.pdf',benor:'https://www.cs.yale.edu/~aspnes/papers/randomized-consensus-survey.pdf',mit:'https://ocw.mit.edu/courses/6-852j-distributed-algorithms-fall-2009/pages/lecture-notes/'};
export const sum=a=>a.reduce((s,x)=>s+x,0),range=n=>Array.from({length:n},(_,i)=>i),f=(x,d=3)=>Number.isFinite(x)?x.toFixed(d):'undefined';
export function rng(seed){let s=seed>>>0;return()=>{s=(Math.imul(s,1664525)+1013904223)>>>0;return(s+.5)/4294967296;};}
export function shuffle(a,r){const b=[...a];for(let j=b.length-1;j>0;j--){const k=Math.floor(r()*(j+1));[b[j],b[k]]=[b[k],b[j]];}return b;}
export function bits(n,mask){return range(n).map(i=>(mask>>i)&1);}
export function consensusCheck(input,decisions,correct=range(input.length)){const chosen=decisions.filter(x=>x!==null);return{agreement:new Set(chosen).size<=1,validity:chosen.every(x=>input.includes(x)),complete:correct.every(i=>decisions[i]!==null),chosen};}
// Crash entry {p,round,to}: in that round p broadcasts only to the listed receivers, then halts.
export function flood(n,input,rounds,crashes=[]){let sets=input.map(x=>[x]),alive=range(n).map(()=>true);const frames=[{sets:sets.map(x=>[...x]),alive:[...alive],messages:[]}];for(let t=1;t<=rounds;t++){const next=sets.map(x=>new Set(x)),messages=[];for(let p=0;p<n;p++)if(alive[p]){const c=crashes.find(c=>c.p===p&&c.round===t);for(let q=0;q<n;q++)if(p!==q&&alive[q]&&(!c||c.to.includes(q))){sets[p].forEach(x=>next[q].add(x));messages.push({p,q,values:[...sets[p]]});}}for(const c of crashes)if(c.round===t)alive[c.p]=false;sets=next.map(x=>[...x].sort());frames.push({sets:sets.map(x=>[...x]),alive:[...alive],messages});}return{frames,sets,alive,decisions:sets.map((s,i)=>alive[i]?Math.min(...s):null)};}
export function hiddenChain(faults,rounds){const n=faults+2,input=range(n).map(i=>i===0?0:1),crashes=range(faults).map(p=>({p,round:p+1,to:[p+1]}));return{n,input,crashes,...flood(n,input,rounds,crashes)};}
export function fullInformation(rounds=4,delivered=rounds){let views=['A:1','B:1'];const messages=[];for(let t=0;t<rounds;t++){const p=t%2,q=1-p,body=views[p],ok=t<delivered;messages.push({p,q,t:t+1,body,ok});if(ok)views[q]+=`|r${t+1}[${body}]`;}return{views,messages};}
// Basic synchronous 2PC: round 1 votes to coordinator, round 2 its decision broadcast.
export function twoPhase(mask=15,crash='none',recipients=1,round=2){const input=bits(4,mask),states=input.map(x=>x?'U':'A'),alive=[true,true,true,true],frames=[{states:[...states],alive:[...alive],messages:[]}];let decision=input.every(Boolean)?'C':'A';for(let t=1;t<=round;t++){const messages=[];if(t===1){for(let p=1;p<4;p++)messages.push({p,q:0,label:String(input[p])});if(crash==='before decision')alive[0]=false;else states[0]=decision;}if(t===2&&alive[0]){for(let q=1;q<4;q++)if(crash!=='during broadcast'||q<=recipients){states[q]=decision;messages.push({p:0,q,label:decision});}if(crash==='during broadcast')alive[0]=false;}frames.push({states:[...states],alive:[...alive],messages});}return{input,states,alive,frames,decision};}
// MIT 6.852 lecture 6, slides 45–52: synchronous 3PC plus rotating recovery.
export function threePhase(mask=15,crashP=0,crashRound=0,partial=1,rounds=12){const input=bits(4,mask),states=input.map(x=>x?'U':'A'),alive=[true,true,true,true],frames=[{states:[...states],alive:[...alive],messages:[],coordinator:0}];for(let t=1;t<=rounds;t++){const c=Math.floor((t-1)/3),phase=(t-1)%3+1,messages=[],old=[...states];if(phase===1&&alive[c]){const heard=range(4).filter(p=>alive[p]&&!(p===crashP&&t===crashRound&&c>=partial));for(const p of heard)if(p!==c)messages.push({p,q:c,label:states[p]});if(c===0)states[c]=heard.length===4&&input.every(Boolean)?'R':'A';else{const reports=heard.map(p=>states[p]);states[c]=reports.includes('A')?'A':reports.includes('C')?'C':reports.every(x=>x==='U')?'A':'R';}}if(phase===2&&alive[c]){const sent=states[c];for(let q=0;q<4;q++)if(q!==c&&alive[q]&&!(c===crashP&&t===crashRound&&q>=partial)){states[q]=sent;messages.push({p:c,q,label:sent});}if(states[c]==='R'&&!(c===crashP&&t===crashRound))states[c]='C';}if(phase===3&&alive[c]&&states[c]==='C')for(let q=0;q<4;q++)if(q!==c&&alive[q]&&!(c===crashP&&t===crashRound&&q>=partial)){states[q]='C';messages.push({p:c,q,label:'C'});}if(t===crashRound)alive[crashP]=false;const invariant=(!states.some(x=>x==='R'||x==='C')||input.every(Boolean))&&(!states.includes('A')||(!states.includes('C')&&!states.some((x,i)=>alive[i]&&x==='R')))&&(!states.includes('C')||!states.some((x,i)=>alive[i]&&x==='U'));frames.push({states:[...states],alive:[...alive],messages,coordinator:c,invariant,old});}return{input,states,alive,frames};}
// Complete initial broadcasts, then a finite actual delivery prefix. Missing crashed-sender messages stay absent.
export function asynchronousAudit(mask=2,quorum=3,seed=1,crash=-1,limit=6){const n=3,input=bits(n,mask),inbox=input.map(x=>[x]),decisions=[null,null,null],r=rng(seed),pending=shuffle(range(n).flatMap(p=>range(n).filter(q=>p!==q&&p!==crash&&q!==crash).map(q=>({p,q,value:input[p]}))),r),frames=[];for(let t=0;t<=Math.min(limit,pending.length);t++){if(t){const e=pending[t-1];inbox[e.q].push(e.value);}for(let p=0;p<n;p++)if(p!==crash&&decisions[p]===null&&inbox[p].length>=quorum)decisions[p]=Math.min(...inbox[p]);frames.push({inbox:inbox.map(x=>[...x]),decisions:[...decisions],event:t?pending[t-1]:null});}return{input,pending,frames,decisions,correct:range(n).filter(p=>p!==crash)};}
export function primitiveConsensus(n=2,mask=1,primitive='TAS',seed=1,steps=12){const input=bits(n,mask),pc=range(n).map(()=>0),prefer=range(n).map(()=>null),decisions=range(n).map(()=>null),r=rng(seed),trace=[];let cell=primitive==='TAS'?0:null;for(let t=0;t<steps;t++){const eligible=range(n).filter(p=>pc[p]<3);if(!eligible.length)break;const p=eligible[Math.floor(r()*eligible.length)];let label;if(pc[p]===0){prefer[p]=input[p];label='publish';}else if(pc[p]===1){if(primitive==='CAS'){if(cell===null)cell=input[p];decisions[p]=cell;}else if(primitive==='TAS'){if(cell===0){cell=1;decisions[p]=input[p];}else if(n===2)decisions[p]=prefer[1-p];else decisions[p]=prefer[(p+1)%n];}else{decisions[p]=Math.min(...prefer.filter(x=>x!==null));}label=primitive;}else label='return';pc[p]++;trace.push({p,label,cell,prefer:[...prefer],decisions:[...decisions]});}return{input,trace,decisions,pc,cell};}
// n=3f+1, trimming f extremes and averaging the surviving endpoints (MIT lecture 6).
export function approximate(input=[0,2,6],rounds=4,faultyLow=-5,faultyHigh=10){let values=[...input];const frames=[{values:[...values],rows:[]}];for(let t=0;t<rounds;t++){const rows=values.map((_,i)=>[...values,i===0?faultyLow:i===1?faultyHigh:(faultyLow+faultyHigh)/2].sort((a,b)=>a-b)),next=rows.map(x=>(x[1]+x[2])/2);values=next;frames.push({values:[...values],rows});}return{frames,values,spread:Math.max(...values)-Math.min(...values)};}
export function sperner(m=4,seed=1,valid=true){const r=rng(seed),vertices=[],lookup=new Map();for(let i=0;i<=m;i++)for(let j=0;j<=m-i;j++){const bary=[m-i-j,i,j],allowed=range(3).filter(k=>!valid||bary[k]>0),color=allowed[Math.floor(r()*allowed.length)],v={i,j,x:(i+.5*j)/m,y:Math.sqrt(3)*j/(2*m),color,bary};lookup.set(i+','+j,vertices.length);vertices.push(v);}const triangles=[];for(let i=0;i<m;i++)for(let j=0;j<m-i;j++){triangles.push([[i,j],[i+1,j],[i,j+1]].map(p=>lookup.get(p.join(','))));if(i+j<m-1)triangles.push([[i+1,j],[i+1,j+1],[i,j+1]].map(p=>lookup.get(p.join(','))));}const colorful=triangles.filter(t=>new Set(t.map(i=>vertices[i].color)).size===3);return{vertices,triangles,colorful};}
export function diamond(same=false){const apply=(s,p,bit)=>{const local=s.local.map((x,i)=>i===p?x+bit:x),buffer=[...s.buffer,`${p}:${local[p]}`].sort();return{local,buffer};},s={local:['',''],buffer:[]},a={p:0,b:'0'},b={p:same?0:1,b:'1'},ab=apply(apply(s,a.p,a.b),b.p,b.b),ba=apply(apply(s,b.p,b.b),a.p,a.b);return{s,a,b,ab,ba,equal:JSON.stringify(ab)===JSON.stringify(ba)};}
export function panel(v,title,{x=[-.15,1.15],y=[-.2,1.2],height=300,axes=false,xlabel='',ylabel='',...rest}={}){return v.stage({title,x,y,height,axes,xlabel,ylabel,gutter:axes!==false,minWidth:260,...rest});}
export function grid(s,rows,{colors={0:'blue',1:'gold',U:'muted',R:'gold',A:'red',C:'green'},label='P'}={}){const n=rows.length,k=Math.max(1,...rows.map(x=>x.length));s.setView([-.8,k+.4],[-.8,n+.4]);for(let i=0;i<n;i++){s.text(label+i,-.55,n-1-i,{size:11,align:'center'});for(let j=0;j<rows[i].length;j++){const value=String(rows[i][j]);s.rect(j-.35,n-1-i-.3,j+.35,n-1-i+.3,{fill:colors[value]||'purple',fillAlpha:.25,stroke:false});s.text(value,j,n-1-i,{size:12,align:'center'});}}}
export function timeline(s,frames,n){const right=frames.length-.4,labelSpace=44;s.setView([-right*labelSpace/Math.max(1,s.width-labelSpace),right],[-.7,n-.3]);for(let p=0;p<n;p++){s.path([[0,n-1-p],[frames.length-1,n-1-p]],{color:'muted',alpha:.35});s.textPx('P'+p,8,s.Y(n-1-p),{size:11,align:'left'});}frames.forEach((F,t)=>{for(const e of F.messages||[])s.path([[Math.max(0,t-.7),n-1-e.p],[t,n-1-e.q]],{color:'blue',alpha:.35});for(let p=0;p<n;p++){const state=F.states?F.states[p]:F.sets[p].join(''),color=state==='C'?'green':state==='A'?'red':state==='R'?'gold':'blue';s.dot(t,n-1-p,{r:F.alive[p]?5:3,color});if(t===frames.length-1)s.text(String(state),t,n-1-p+.23,{size:10,align:'center'});}});}
// Ben-Or crash protocol, Aspnes survey Algorithm 1. Decisions do not stop participation.
export function benOr(n=5,t=2,mask=10,seed=1,budget=1000,crash=-1,policy='random'){const random=rng(seed),coin=rng(seed^0x9e3779b9),input=bits(n,mask),P=range(n).map(p=>({r:1,phase:1,pref:input[p],decision:null,boxes:new Map()})),queue=[],history=[];let serial=0,delivered=0;const correct=range(n).filter(p=>p!==crash);const send=(p,phase,value)=>{for(const q of correct)queue.push({p,q,r:P[p].r,phase,value,id:serial++});};for(const p of correct)send(p,1,P[p].pref);for(let step=0;step<budget&&queue.length;step++){// Oldest delivery every n events bounds starvation, independent of future coin flips.
 delivered=step+1;const k=policy==='FIFO'||step%n===0?0:Math.floor(random()*queue.length),e=queue.splice(k,1)[0],p=P[e.q],key=e.r+':'+e.phase;if(!p.boxes.has(key))p.boxes.set(key,new Map());p.boxes.get(key).set(e.p,e.value);let advanced=false;while(true){const box=p.boxes.get(p.r+':'+p.phase);if(!box||box.size<n-t)break;const received=[...box.values()].slice(0,n-t),before={r:p.r,phase:p.phase};if(p.phase===1){let v=null;for(const b of[0,1])if(received.filter(x=>x===b).length>n/2)v=b;p.phase=2;send(e.q,2,v);}else{const rat=received.filter(x=>x!==null);if(rat.length){p.pref=rat[0];if(rat.length>t&&p.decision===null)p.decision=rat[0];}else p.pref=+(coin()<.5);p.r++;p.phase=1;send(e.q,1,p.pref);}history.push({step:step+1,p:e.q,before,r:p.r,phase:p.phase,pref:p.pref,decision:p.decision});advanced=true;}if(correct.every(i=>P[i].decision!==null))return{input,P,correct,history,delivered:step+1,complete:true,queue:queue.length};if(!advanced&&step===budget-1)break;}return{input,P,correct,history,delivered,complete:correct.every(i=>P[i].decision!==null),queue:queue.length};}
export function benOrTrials(n,t,mask,seed,R=32,budget=1000,crash=-1,policy='random'){const runs=range(R).map(i=>benOr(n,t,mask,seed*1009+i,budget,crash,policy)),success=runs.filter(x=>x.complete).length,p=success/R;return{runs,success,rate:p,mcse:Math.sqrt(p*(1-p)/R),censored:R-success};}
// Finite prefix of an authored oracle history; membership in Omega is an infinite-tail property.
export function omegaTrace(n=4,gst=8,mode='stabilizes',length=24,crash=3){const leader=range(n).find(i=>i!==crash),outputs=range(length).map(t=>range(n).map(p=>mode==='wrong tail'&&t>=gst?crash:mode==='oscillates'?((t+p)%n):t<gst?(t+p)%n:leader));return{outputs,leader,correct:range(n).filter(i=>i!==crash),tailGood:outputs.slice(gst).every(row=>range(n).filter(p=>p!==crash).every(p=>row[p]===leader))};}
// Finite single-decree Paxos-style ballot execution, not the DLS paper's exact protocol.
export function ballots(seed=1,gst=3,delay=2,rounds=14,unstable=false,crash=3){const n=5,q=3,r=rng(seed),acceptors=range(n).map(()=>({promise:-1,accepted:null})),events=[],frames=[],chosen=[],attempts=[];for(let clock=0;clock<rounds;clock++){// Before GST messages may take arbitrary bounded illustrative delays; afterwards bound=delay.
 const leader=clock<gst||unstable?clock%3:0,ballot=clock*5+leader,proposal=leader%2,attempt={ballot,leader,proposal,promises:[],votes:[],chosen:null};const launch=clock<gst||unstable||(clock-gst)%(2*delay+1)===0;if(launch)attempts.push(attempt);const wait=clock<gst?1+Math.floor(r()*8):delay;if(launch)for(let p=0;p<n;p++)if(p!==crash)events.push({at:clock+wait,p,type:'prepare',attempt});for(let i=0;i<events.length;){const e=events[i];if(e.at>clock){i++;continue;}events.splice(i,1);const a=acceptors[e.p],A=e.attempt;if(e.type==='prepare'){if(A.ballot>a.promise){a.promise=A.ballot;A.promises.push({p:e.p,accepted:a.accepted?{...a.accepted}:null});if(A.promises.length===q){const previous=A.promises.map(x=>x.accepted).filter(Boolean).sort((a,b)=>b.ballot-a.ballot),value=previous.length?previous[0].value:A.proposal;A.value=value;for(let p=0;p<n;p++)if(p!==crash)events.push({at:clock+delay,p,type:'accept',attempt:A,value});}}}else if(A.ballot>=a.promise){a.promise=A.ballot;a.accepted={ballot:A.ballot,value:e.value};A.votes.push(e.p);if(A.votes.length===q){A.chosen=e.value;chosen.push({clock,ballot:A.ballot,value:e.value});}}}frames.push({clock,leader,acceptors:acceptors.map(a=>({promise:a.promise,accepted:a.accepted?{...a.accepted}:null})),chosen:chosen.map(x=>({...x}))});}return{frames,chosen,attempts,agreement:new Set(chosen.map(x=>x.value)).size<=1};}
// Fresh immutable cells and per-cell consensus choices, with the original cyclic helping rule.
export function universal(n=3,seed=1,steps=15,halt=-1){const r=rng(seed),cells=[{id:0,seq:1,state:0,after:null,inv:0}],announce=range(n).map(p=>{cells.push({id:p+1,seq:0,state:null,after:null,inv:p+1});return p+1;}),head=range(n).map(()=>0),iterations=range(n).map(()=>0),frames=[],log=[];for(let t=0;t<steps;t++){const eligible=range(n).filter(p=>p!==halt&&cells[announce[p]].seq===0);if(!eligible.length)break;const p=eligible[Math.floor(r()*eligible.length)];if(iterations[p]===0)head[p]=head.reduce((a,b)=>cells[a].seq>=cells[b].seq?a:b,head[p]);const c=cells[head[p]],help=announce[c.seq%n],prefer=cells[help].seq===0?help:announce[p];if(c.after===null)c.after=prefer;const d=cells[c.after];if(d.seq===0){d.state=c.state+d.inv;d.seq=c.seq+1;log.push({p:d.id-1,inv:d.inv,state:d.state,seq:d.seq});}head[p]=d.id;iterations[p]++;frames.push({p,head:[...head],iterations:[...iterations],log:log.map(x=>({...x})),done:announce.map(i=>cells[i].seq>0)});}return{cells,announce,head,iterations,frames,log};}
export function player(v,get,key,code){const build=()=>get().map((F,i)=>({...F,lines:i===0?[1]:(i-1)%3===0?[2,3,4,5]:(i-1)%3===1?[6,7]:[8,9],note:i===0?'Initial local states':`Boundary ${i}: inspect the retained local states.`}));const S=v.steps({frames:build,code,codeTitle:'synchronous recovery rules',codePos:'below',still:'end',start:'end'});let last=key();v.render(()=>{const next=key();if(next!==last){last=next;S.reset(undefined,{at:'keep'});}});return S;}
